// Synchronous exception from current EL with SPx: note it and skip the instruction.
__asm__(".balign 2048\nvectors:\n .skip 0x200\n"
        " mrs x9, elr_el1\n add x9, x9, #4\n msr elr_el1, x9\n"
        " adrp x9, undef_hit\n mov x10, #1\n str x10, [x9, :lo12:undef_hit]\n eret\n"
        " .skip 0x5e4\n");

__asm__(".globl _start\n_start:\n ldr x0, =0x40100000\n mov sp, x0\n bl main_\n1: b 1b\n");
